cat > main.js <<'E'
const T = 32, W = 800, H = 480;
// # solid  c coin  E enemy  P start  G goal  ^ spikes
const LEVELS = [[
"........................................",
"........................................",
"........................................",
"........................................",
"........................................",
"..................ccc...................",
"..........ccc....#####..............G...",
"........#####...................#######.",
"...c....................c...............",
"..###.......E.........#####.............",
"..................................c.....",
"P.......####..............c.....###.....",
"#########..###..^^^.#############..#####",
"#########..###########.........#########",
"########################################"
],[
"................................................",
"................................................",
"................................................",
"..........................ccc...................",
"...............ccc.......#####..................",
"..............#####.............................",
"......ccc.......................c...........G...",
"....#####...........E.......#####.........######",
"................#######.....................#...",
".c..........................c...............#...",
"###......E.....^^^........#####......ccc....#...",
"P........####..#####...........^^^..#####...#...",
"#######..#####.#####..####..########.........#..",
"#######..#####.#####..####..########..^^^..###..",
"################################################"
]];

class Menu extends Phaser.Scene {
  constructor(){ super('menu'); }
  create(){
    this.add.text(W/2,150,'COIN HOPPER',{fontSize:'56px',color:'#ffd23f',fontStyle:'bold'}).setOrigin(.5);
    this.add.text(W/2,250,'Arrows / WASD to move\nUP / W / SPACE to jump (press again in the air to double jump)\nStomp the red blob. Grab coins. Reach the flag.',
      {fontSize:'18px',color:'#fff',align:'center'}).setOrigin(.5);
    const s=this.add.text(W/2,360,'Press SPACE to start',{fontSize:'28px',color:'#7bdff2'}).setOrigin(.5);
    this.tweens.add({targets:s,alpha:.3,yoyo:true,repeat:-1,duration:600});
    this.input.keyboard.once('keydown-SPACE',()=>this.scene.start('play',{level:0,score:0}));
  }
}

class Play extends Phaser.Scene {
  constructor(){ super('play'); }
  init(d){ this.level=d.level; this.startScore=d.score; this.score=d.score; this.dead=false; this.won=false;
    this.coyote=0; this.buffer=0; this.jumps=0; }
  makeTextures(){
    if(this.textures.exists('tile')) return;
    const g=this.make.graphics({add:false});
    const gen=(k,w,h,fn)=>{g.clear();fn(g);g.generateTexture(k,w,h);};
    gen('tile',T,T,g=>{g.fillStyle(0x5b3a29).fillRect(0,0,T,T);g.fillStyle(0x4caf50).fillRect(0,0,T,8);g.lineStyle(1,0x3a2418).strokeRect(0,0,T,T);});
    gen('player',24,30,g=>{g.fillStyle(0x3a86ff).fillRect(0,0,24,30);g.fillStyle(0xffffff).fillRect(13,6,8,8);g.fillStyle(0).fillRect(17,8,4,4);});
    gen('coin',16,16,g=>{g.fillStyle(0xffd23f).fillCircle(8,8,7);g.fillStyle(0xfff3b0).fillCircle(6,6,3);});
    gen('enemy',28,24,g=>{g.fillStyle(0xe63946).fillRoundedRect(0,0,28,24,8);g.fillStyle(0xffffff).fillRect(5,6,7,7).fillRect(16,6,7,7);g.fillStyle(0).fillRect(7,8,3,3).fillRect(18,8,3,3);});
    gen('spike',T,16,g=>{g.fillStyle(0xcccccc);for(let i=0;i<4;i++)g.fillTriangle(i*8,16,i*8+4,0,i*8+8,16);});
    gen('flag',T,64,g=>{g.fillStyle(0xdddddd).fillRect(4,0,4,64);g.fillStyle(0x2ec4b6).fillTriangle(8,2,30,12,8,22);});
    g.destroy();
  }
  create(){
    this.makeTextures();
    const map=LEVELS[this.level]; this.map=map;
    const cols=map[0].length, rows=map.length;
    this.add.rectangle(0,0,cols*T,rows*T,this.level?0x2b2d42:0x87ceeb).setOrigin(0).setDepth(-5);
    this.physics.world.setBounds(0,0,cols*T,rows*T+200);
    this.solids=this.physics.add.staticGroup(); this.coins=this.physics.add.staticGroup();
    this.spikes=this.physics.add.staticGroup(); this.enemies=this.physics.add.group();
    let sx=50, sy=100;
    map.forEach((row,r)=>[...row].forEach((ch,c)=>{
      const x=c*T+T/2,y=r*T+T/2;
      if(ch==='#') this.solids.create(x,y,'tile');
      else if(ch==='c') this.coins.create(x,y,'coin').setSize(14,14);
      else if(ch==='^'){ const s=this.spikes.create(x,y+8,'spike'); s.body.setSize(26,10).setOffset(3,6); }
      else if(ch==='P'){ sx=x; sy=y; }
      else if(ch==='G'){ this.goal=this.physics.add.staticImage(x,y-16,'flag'); }
      else if(ch==='E'){ const e=this.enemies.create(x,y+4,'enemy'); e.setCollideWorldBounds(true); e.dir=-1; }
    }));
    this.coins.refresh?.();
    this.player=this.physics.add.sprite(sx,sy,'player');
    this.player.body.setMaxVelocityY(700);
    this.physics.add.collider(this.player,this.solids);
    this.physics.add.collider(this.enemies,this.solids);
    this.physics.add.overlap(this.player,this.coins,(p,c)=>{c.disableBody(true,true);this.score+=10;this.hud();this.cameras.main.flash(60,255,230,100,true);});
    this.physics.add.overlap(this.player,this.spikes,()=>this.die());
    this.physics.add.overlap(this.player,this.goal,()=>this.finish());
    this.physics.add.overlap(this.player,this.enemies,(p,e)=>{
      if(p.body.velocity.y>50 && p.body.bottom-e.body.top<16){
        e.disableBody(true,true); p.setVelocityY(-380); this.jumps=1; this.score+=50; this.hud();
        this.cameras.main.shake(80,.004);
      } else this.die();
    });
    const cam=this.cameras.main; cam.setBounds(0,0,cols*T,rows*T); cam.startFollow(this.player,true,.12,.12);
    cam.setDeadzone(60,40);
    const kb=this.input.keyboard;
    this.keys=kb.addKeys({left:'LEFT',right:'RIGHT',a:'A',d:'D',up:'UP',w:'W',space:'SPACE'});
    this.hudText=this.add.text(10,8,'',{fontSize:'20px',color:'#fff',stroke:'#000',strokeThickness:4}).setScrollFactor(0).setDepth(10);
    this.hud();
  }
  hud(){ this.hudText.setText(`Level ${this.level+1}/${LEVELS.length}   Score ${this.score}`); }
  die(){
    if(this.dead||this.won) return; this.dead=true;
    this.player.setTint(0xff0000).setVelocity(0,-300); this.player.body.checkCollision.none=true;
    this.cameras.main.shake(200,.01);
    this.time.delayedCall(700,()=>this.scene.restart({level:this.level,score:this.startScore}));
  }
  finish(){
    if(this.won||this.dead) return; this.won=true; this.player.setVelocity(0,0); this.player.body.moves=false;
    this.time.delayedCall(500,()=>{
      if(this.level+1<LEVELS.length) this.scene.restart({level:this.level+1,score:this.score});
      else this.scene.start('win',{score:this.score});
    });
  }
  solidAt(x,y){ const c=Math.floor(x/T),r=Math.floor(y/T); return this.map[r]?.[c]==='#'; }
  update(time,delta){
    const p=this.player,b=p.body,k=this.keys,dt=delta/1000;
    this.enemies.getChildren().forEach(e=>{
      if(!e.active) return;
      const ahead=e.x+e.dir*(e.width/2+4);
      if(e.body.blocked.left) e.dir=1; else if(e.body.blocked.right) e.dir=-1;
      else if(e.body.blocked.down && !this.solidAt(ahead,e.body.bottom+4)) e.dir*=-1;
      e.setVelocityX(e.dir*70);
    });
    if(this.dead||this.won) return;
    const L=k.left.isDown||k.a.isDown, R=k.right.isDown||k.d.isDown;
    const target=(R-L)*190, acc=b.blocked.down?1800:1100;
    b.setVelocityX(Phaser.Math.Linear? b.velocity.x+Phaser.Math.Clamp(target-b.velocity.x,-acc*dt,acc*dt):target);
    if(L!==R) p.setFlipX(L);
    if(b.blocked.down){ this.coyote=.1; this.jumps=0; }
    this.coyote-=dt; this.buffer-=dt;
    const pressed=[k.up,k.w,k.space].some(x=>Phaser.Input.Keyboard.JustDown(x));
    const held=k.up.isDown||k.w.isDown||k.space.isDown;
    if(pressed) this.buffer=.12;
    if(this.buffer>0){
      if(this.coyote>0){ b.setVelocityY(-470); this.jumps=1; this.coyote=0; this.buffer=0; }
      else if(this.jumps<2 && pressed){ b.setVelocityY(-420); this.jumps=2; this.buffer=0; this.puff(); }
    }
    if(!held && b.velocity.y<-150) b.setVelocityY(b.velocity.y*.6); // variable height
    b.setGravityY(b.velocity.y>0?500:0);
    if(p.y>this.map.length*T+60) this.die();
  }
  puff(){ const c=this.add.circle(this.player.x,this.player.body.bottom,8,0xffffff,.8);
    this.tweens.add({targets:c,scale:2.5,alpha:0,duration:250,onComplete:()=>c.destroy()}); }
}

class Win extends Phaser.Scene {
  constructor(){ super('win'); }
  create(d){
    this.add.text(W/2,140,'YOU WIN!',{fontSize:'64px',color:'#ffd23f',fontStyle:'bold'}).setOrigin(.5);
    this.add.text(W/2,240,`Final score: ${d.score}`,{fontSize:'30px',color:'#fff'}).setOrigin(.5);
    this.add.text(W/2,330,'Press SPACE to play again',{fontSize:'24px',color:'#7bdff2'}).setOrigin(.5);
    this.input.keyboard.once('keydown-SPACE',()=>this.scene.start('menu'));
  }
}

new Phaser.Game({type:Phaser.AUTO,width:W,height:H,backgroundColor:'#111',pixelArt:true,
  physics:{default:'arcade',arcade:{gravity:{y:900},debug:false}},
  scale:{mode:Phaser.Scale.FIT,autoCenter:Phaser.Scale.CENTER_BOTH},
  scene:[Menu,Play,Win]});
